Lemma maps_subtract_pos : forall (l : list (word * word)) lo hi,
  Forall (fun iv : word * word => 0 < bv_unsigned (snd iv)) l ->
  Forall (fun iv : word * word => 0 < bv_unsigned (snd iv)) (maps_subtract l lo hi).
Proof.
