Lemma vis_add_sound : forall E cs b n k cs2 R FULL model,
  vis_add A LIMIT cs b n k = Some cs2 ->
  cs_ok E cs R FULL model ->
  know_ok SEGS E (Mr E cs2 model FULL) k ->
  cs_ok E cs2 R FULL model.
Proof.
